CREATE TABLE `ProductCategory` (`slug` VARCHAR(80) NOT NULL, `name` VARCHAR(191) NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (`slug`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CostumeProduct` (
 `slug` VARCHAR(100) NOT NULL, `code` VARCHAR(40) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `image` VARCHAR(500) NOT NULL, `price` INTEGER NOT NULL, `categorySlug` VARCHAR(80) NOT NULL, `gender` VARCHAR(20) NOT NULL, `availability` VARCHAR(20) NOT NULL, `minHeight` INTEGER NOT NULL, `maxHeight` INTEGER NOT NULL, `minWeight` INTEGER NOT NULL, `maxWeight` INTEGER NOT NULL, `tags` JSON NOT NULL, `accessories` JSON NOT NULL, `badge` VARCHAR(80) NOT NULL, `badgeTone` VARCHAR(20) NOT NULL DEFAULT 'red', `popularity` INTEGER NOT NULL DEFAULT 0, `published` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL,
 PRIMARY KEY (`slug`), UNIQUE INDEX `CostumeProduct_code_key` (`code`), INDEX `CostumeProduct_published_categorySlug_price_idx` (`published`, `categorySlug`, `price`), CONSTRAINT `CostumeProduct_categorySlug_fkey` FOREIGN KEY (`categorySlug`) REFERENCES `ProductCategory` (`slug`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
